"""Explicit scientific inputs for the bounded Tokamak roster author.

Complete source digests are numerical commitments. Public identifiers never
supply entropy. Additional collision-driven candidates require caller-supplied
commitments instead of reconstructing a historical namespace.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal
from typing import ClassVar

from empirical_lawhood.kernel.serialization import CanonicalRecord, validate_sha256

_ROLES = frozenset(
    (
        "source-qualification",
        "matched-evaluation-primary",
        "matched-evaluation-reserve",
        "prospective-efficacy",
        "prospective-hold",
        "active-route-canary",
        "hold-route-canary",
    )
)
_STAGES = frozenset(
    (
        "excluded-source-qualification",
        "primary-matched-evaluation",
        "reserve-matched-evaluation",
        "excluded-route-qualification",
        "prospective-primary",
        "prospective-reserve",
    )
)
_EPISODE_ROLES = frozenset(
    (
        "future-ip",
        "lower-ip",
        "native-hold",
        "wrong-sign-ip",
        "efficacy-active",
        "efficacy-hold",
        "hold-control",
        "route-hold-repeat",
    )
)


def _require_role_counter(role: str, counter: int) -> None:
    if role not in _ROLES or type(counter) is not int or counter < 0:
        raise ValueError("roster scientific input has another role or counter")


@dataclass(frozen=True, slots=True)
class GymToraxRosterStreamInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = (
        "empirical-lawhood/composition/tokamak-control-replication/roster-scientific-word-input"
    )
    role: str
    counter: int
    full_sha256_blocks: tuple[str, ...]

    def __post_init__(self) -> None:
        _require_role_counter(self.role, self.counter)
        if (
            not isinstance(self.full_sha256_blocks, tuple)
            or len(self.full_sha256_blocks) != 2
        ):
            raise ValueError(
                "roster candidate requires two complete scientific word blocks"
            )
        for digest in self.full_sha256_blocks:
            validate_sha256(digest, field_name="full_sha256_blocks")

    @property
    def key(self) -> tuple[str, int]:
        return self.role, self.counter

    @property
    def words(self) -> tuple[int, ...]:
        return tuple(
            int(digest[offset : offset + 16], 16)
            for digest in self.full_sha256_blocks
            for offset in range(0, 64, 16)
        )


@dataclass(frozen=True, slots=True)
class GymToraxRosterEnvironmentSeedInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = (
        "empirical-lawhood/composition/tokamak-control-replication/roster-scientific-environment-seed"
    )
    stage: str
    role: str
    counter: int
    cell_kind: str
    numerical_member_role: str
    episode_role: str
    full_seed_sha256: str

    def __post_init__(self) -> None:
        _require_role_counter(self.role, self.counter)
        if self.stage not in _STAGES or self.cell_kind not in ("b", "bt", "c", "t"):
            raise ValueError(
                "environment seed has another scientific stage or cell kind"
            )
        if (
            self.numerical_member_role not in ("primary", "refined")
            or self.episode_role not in _EPISODE_ROLES
        ):
            raise ValueError(
                "environment seed has another numerical member or episode role"
            )
        validate_sha256(self.full_seed_sha256, field_name="full_seed_sha256")

    @property
    def key(self) -> tuple[str, str, int, str, str, str]:
        return (
            self.stage,
            self.role,
            self.counter,
            self.cell_kind,
            self.numerical_member_role,
            self.episode_role,
        )

    @property
    def environment_seed(self) -> int:
        return (int(self.full_seed_sha256[:16], 16) & (2**63 - 1)) or 1


@dataclass(frozen=True, slots=True)
class GymToraxPreparationCustodyInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = (
        "empirical-lawhood/composition/tokamak-control-replication/preparation-scientific-custody-input"
    )
    initial_temperature_scale: Decimal
    initial_density_nbar: Decimal
    bootstrap_multiplier: Decimal
    inner_transport_scale: Decimal
    source_preparation_fingerprint: str

    def __post_init__(self) -> None:
        if any(
            not isinstance(value, Decimal) or not value.is_finite()
            for value in self.key
        ):
            raise ValueError(
                "preparation custody requires four finite numerical operands"
            )
        validate_sha256(
            self.source_preparation_fingerprint,
            field_name="source_preparation_fingerprint",
        )

    @property
    def key(self) -> tuple[Decimal, Decimal, Decimal, Decimal]:
        return (
            self.initial_temperature_scale,
            self.initial_density_nbar,
            self.bootstrap_multiplier,
            self.inner_transport_scale,
        )


@dataclass(frozen=True, slots=True)
class GymToraxCellIdentityCustodyInput(CanonicalRecord):
    SCHEMA: ClassVar[str] = (
        "empirical-lawhood/composition/tokamak-control-replication/cell-scientific-custody-input"
    )
    role: str
    counter: int
    cell_kind: str
    source_cell_identity_sha256: str

    def __post_init__(self) -> None:
        _require_role_counter(self.role, self.counter)
        if self.cell_kind not in ("b", "bt", "c", "t"):
            raise ValueError("cell custody has another scientific cell kind")
        validate_sha256(
            self.source_cell_identity_sha256, field_name="source_cell_identity_sha256"
        )

    @property
    def key(self) -> tuple[str, int, str]:
        return self.role, self.counter, self.cell_kind


@dataclass(frozen=True, slots=True)
class GymToraxRosterScientificInputs(CanonicalRecord):
    SCHEMA: ClassVar[str] = (
        "empirical-lawhood/composition/tokamak-control-replication/roster-scientific-input-census"
    )
    stream_inputs: tuple[GymToraxRosterStreamInput, ...]
    environment_seed_inputs: tuple[GymToraxRosterEnvironmentSeedInput, ...]
    preparation_custody_inputs: tuple[GymToraxPreparationCustodyInput, ...]
    cell_identity_custody_inputs: tuple[GymToraxCellIdentityCustodyInput, ...]

    def __post_init__(self) -> None:
        for rows, record_type in (
            (self.stream_inputs, GymToraxRosterStreamInput),
            (self.environment_seed_inputs, GymToraxRosterEnvironmentSeedInput),
            (self.preparation_custody_inputs, GymToraxPreparationCustodyInput),
            (self.cell_identity_custody_inputs, GymToraxCellIdentityCustodyInput),
        ):
            if (
                not isinstance(rows, tuple)
                or not rows
                or any(not isinstance(row, record_type) for row in rows)
            ):
                raise ValueError(
                    "roster requires a nonempty typed scientific input census"
                )
            keys = tuple(row.key for row in rows)
            if keys != tuple(sorted(set(keys))):
                raise ValueError(
                    "roster scientific inputs must be complete, ordered and unique by role"
                )

    def stream_input(self, role: str, counter: int) -> GymToraxRosterStreamInput:
        for row in self.stream_inputs:
            if row.key == (role, counter):
                return row
        raise ValueError(
            f"missing scientific word input for {role} counter {counter}; supply a complete numeric census"
        )

    def environment_seed_input(
        self, key: tuple[str, str, int, str, str, str]
    ) -> GymToraxRosterEnvironmentSeedInput:
        for row in self.environment_seed_inputs:
            if row.key == key:
                return row
        raise ValueError(
            f"missing scientific environment seed input for {key}; supply a complete numeric census"
        )

    def preparation_input(
        self, coordinates: tuple[Decimal, Decimal, Decimal, Decimal]
    ) -> GymToraxPreparationCustodyInput:
        for row in self.preparation_custody_inputs:
            if row.key == coordinates:
                return row
        raise ValueError(
            "missing original preparation custody commitment for numerical operands; supply a complete explicit census"
        )

    def cell_identity_input(
        self, role: str, counter: int, cell_kind: str
    ) -> GymToraxCellIdentityCustodyInput:
        for row in self.cell_identity_custody_inputs:
            if row.key == (role, counter, cell_kind):
                return row
        raise ValueError(
            f"missing original cell custody commitment for {role} counter {counter} kind {cell_kind}; supply a complete explicit census"
        )


